'use strict';

/**
 * Applies the NVD-verified CVSS corrections ledger (data/cvss-corrections.json,
 * produced by scripts/verify-cvss-provenance.js) to intelligence records.
 *
 * Legacy records persisting in the rolling api/intel/live.json window and in
 * api/intel/cve/*.json carry a CVSS of 9.5 that, for 119 of 123 CVEs verified
 * on 2026-09-30, does not match the authoritative NVD/CNA score. Those files
 * are regenerated by the 30-minute pipeline, so the correction is a
 * stable reviewed ledger applied at the two places intelligence leaves the
 * system: the API serving path (api/_lib/intel.js) and the public static
 * build (scripts/build-cloudflare-assets.js).
 *
 * Only records whose id is in the ledger and that already carry a `cvss`
 * field are touched. A ledger status other than VERIFIED withholds the score
 * (null) rather than keeping an unsupported number.
 */

const LEDGER = require('../../data/cvss-corrections.json');

const BY_ID = new Map((LEDGER.entries || []).map(e => [String(e.id).toUpperCase(), e]));

function recordId(record) {
  return String((record && (record.id || record.cve_id)) || '').toUpperCase();
}

function correctionFor(id) {
  return BY_ID.get(String(id || '').toUpperCase()) || null;
}

function applyCvssCorrection(record) {
  if (!record || typeof record !== 'object' || !Object.prototype.hasOwnProperty.call(record, 'cvss')) return record;
  const entry = BY_ID.get(recordId(record));
  if (!entry) return record;
  const verified = entry.status === 'VERIFIED' && typeof entry.verified_cvss === 'number';
  return {
    ...record,
    cvss: verified ? entry.verified_cvss : null,
    cvss_status: entry.status,
    cvss_source: verified ? `NVD CVE API 2.0 (${entry.evidence.source}, ${entry.evidence.metric})` : null,
    ...(verified && entry.evidence.vector ? { cvss_vector: entry.evidence.vector } : {}),
  };
}

// Legacy-record integrity (ICF-P1-003). Records persisted from older
// generator versions contradict their own provenance: source/merged_sources
// name the CISA KEV catalog while cisa_kev is false, and references are two
// URLs joined by " ; " (fixed at ingestion by extractHttpUrls, not in the
// persisted window). Both are reconciled from the record's own data.
const KEV_SOURCE = 'cisa_kev';
// Only structured indicator feeds contribute IOCs (fetch-live-intel.js). Legacy
// records from advisory/news sources carry regex hits from vulnerability text
// (vendor domains, fix-commit SHAs, CVE ids typed "indicator", 169.254.169.254),
// which must not reach customer blocklists. ICF-P0-009.
const STRUCTURED_IOC_SOURCES = new Set(['urlhaus', 'threatfox', 'malwarebazaar', 'otx']);
function recordSources(record) {
  const out = [];
  if (typeof record.source === 'string') out.push(record.source);
  for (const k of ['merged_sources', 'sources']) if (Array.isArray(record[k])) out.push(...record[k]);
  return out;
}
function listedByKevProvenance(record) {
  if (record.source === KEV_SOURCE) return true;
  return ['merged_sources', 'sources'].some(k => Array.isArray(record[k]) && record[k].includes(KEV_SOURCE));
}
function reconcileLegacyRecord(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) return record;
  let out = record;
  if (record.cisa_kev === false && listedByKevProvenance(record)) {
    out = { ...out, cisa_kev: true, kev_status_basis: 'record provenance: CISA KEV catalog source' };
  }
  if (Array.isArray(record.iocs) && record.iocs.length && !recordSources(record).some(s => STRUCTURED_IOC_SOURCES.has(s))) {
    out = { ...out, iocs: [], ioc_status: 'WITHHELD_UNVETTED', ioc_withheld_count: record.iocs.length,
      ...(Object.prototype.hasOwnProperty.call(record, 'ioc_count') ? { ioc_count: 0 } : {}) };
  }
  if (Array.isArray(record.refs) && record.refs.some(r => typeof r === 'string' && /\s;\s/.test(r))) {
    const refs = [...new Set(record.refs.flatMap(r => String(r).split(/\s*;\s*/)).filter(r => /^https?:\/\/\S+$/i.test(r)))];
    out = { ...out, refs };
  }
  return out;
}

function applyRecordCorrections(record) {
  return reconcileLegacyRecord(applyCvssCorrection(record));
}

// Scalar form for callers that rebuild records field by field.
function correctedScore(id, served) {
  const entry = correctionFor(id);
  if (!entry) return typeof served === 'number' ? served : null;
  return entry.status === 'VERIFIED' && typeof entry.verified_cvss === 'number' ? entry.verified_cvss : null;
}

// Corrects a parsed public intel document: a single record, a list, or any
// object whose `items` array holds records. Returns { doc, changed }.
function applyToDocument(doc) {
  let changed = 0;
  const fix = r => { const out = applyRecordCorrections(r); if (out !== r) changed += 1; return out; };
  let result = doc;
  if (Array.isArray(doc)) result = doc.map(fix);
  else if (doc && typeof doc === 'object') {
    result = fix(doc);
    if (Array.isArray(result.items)) result = { ...result, items: result.items.map(fix) };
  }
  return { doc: result, changed };
}

// Cheap pre-check so the build only parses files that can need a correction.
function mentionsLedgerId(text) {
  if (!BY_ID.size || text.indexOf('"cvss"') === -1) return false;
  for (const id of BY_ID.keys()) if (text.indexOf(id) !== -1) return true;
  return false;
}
function needsCorrection(text) {
  return mentionsLedgerId(text)
    || /"iocs":\s*\[\s*\{/.test(text)
    || (text.indexOf('"cisa_kev"') !== -1 && /"cisa_kev":\s*false/.test(text) && text.indexOf('"' + KEV_SOURCE + '"') !== -1)
    || /\s;\shttps?:\/\//.test(text);
}

module.exports = { STRUCTURED_IOC_SOURCES, LEDGER, correctionFor, correctedScore, applyCvssCorrection, reconcileLegacyRecord, applyRecordCorrections, applyToDocument, mentionsLedgerId, needsCorrection };
